from lib import *
S = SS('q9')
steps = [
    step("两个速度相同的消费者(每条 5 ms)订阅同一个队列、prefetch=1,队列里 40 条:前 12 条完成的顺序是 ABABABABBAAB——大体交替,最终 A 21 条、B 19 条。RabbitMQ 把消息依次轮流投给有空位的消费者(轮询),而且是“有空位才投”:谁的未确认数没到 prefetch 谁才能接收。顺序里有 BB、AA,是因为完成顺序受调度影响,不是投递顺序错乱。", t=tl(S(1)), mark=lidx(S(1), '投递给谁'), done=lidx(S(1), '投递给谁'), kv=KV([['分发方式', '轮询给有空位的消费者'], ['相同速度', '各 20 条'], ['有空位', 'unacked < prefetch']], ['分发方式'])),
    step("一快一慢(A 每条 2 ms,B 每条 20 ms),600 条:prefetch 不限(0)时 A 拿到 250、B 拿了 350,总耗时 9.37 s——慢的那个拿到的比快的还多,分法既不是均分也不按速度,而且在我多次运行里每次分法都不同(A 拿过 200、250、400);prefetch=100 时 A 458、B 142,3.75 s;prefetch=10 时 527 / 73,1.90 s;prefetch=1 时 531 / 69,1.83 s,已经接近“按速度比例”分的理想值(约 1.09 s)。越小的 prefetch,越能让快的消费者多拿。", t=tl(S(2)), mark=lidx(S(2), '0(无限)', '100 '), done=lidx(S(2), '10 ', '1  ', '理想情况'), b=bars([['prefetch 0', 9.37, '9.37 s'], ['prefetch 100', 3.75, '3.75 s'], ['prefetch 10', 1.9, '1.90 s'], ['prefetch 1', 1.83, '1.83 s']], 9.37, mark=[0], done=[2, 3]), kv=KV([['prefetch=0', '9.37 s,分配不稳定'], ['prefetch=10', '1.90 s,快的拿 527'], ['prefetch=1', '1.83 s,快的拿 531']], ['prefetch=0'])),
    step("一个卡住的消费者(收到消息既不处理也不 ack):它扣住的消息数正好等于 prefetch。prefetch=1 时它只拿 1 条,另一个正常的消费者 A 处理了 500 条里的 499;prefetch=10 时被扣住 10 条,A 处理 490;prefetch=100 时扣住 100 条,A 只处理 400。8 秒后队列的 (ready, unacked) 分别是 (0, 1)、(0, 10)、(0, 100)——那些消息谁都拿不到,直到卡住的消费者断开或被 consumer_timeout 踢掉(第 24 篇)。", t=tl(S(3)), mark=lidx(S(3), '100  ', '(0, 100)'), done=lidx(S(3), '1    ', '10   ', '卡住的消费者断开'), b=bars([['prefetch 1 扣住', 1, '1 条'], ['prefetch 10 扣住', 10, '10 条'], ['prefetch 100 扣住', 100, '100 条']], 100, mark=[2], done=[0, 1]), kv=KV([['卡住的消费者', '扣住 prefetch 条'], ['别人', '拿不到这批'], ['解除', '断开 / consumer_timeout']], ['卡住的消费者'])),
    step("消费者优先级(x-priority):A 优先级 10、B 优先级 0,各自每条 20 ms(单个容量约 50 条/秒)、prefetch=1,发布 200 条。发布速率 20 条/秒时 A 拿了 199、B 只有 1;45 条/秒时 108 / 92;80 条/秒时 100 / 100;120 条/秒时 100 / 100。消息优先给高优先级的消费者,只有它的 prefetch 已满(正在处理上一条)时,才溢出给低优先级的——速率低于一个消费者的处理能力时低优先级几乎拿不到,所以优先级适合做“主备”或“溢出”。", t=tl(S(4)), mark=lidx(S(4), '20   ', '80   '), done=lidx(S(4), '45   ', '120  '), b=bars([['20/s: A', 199, '199'], ['20/s: B', 1, '1'], ['45/s: A', 108, '108'], ['45/s: B', 92, '92'], ['80/s: A', 100, '100'], ['80/s: B', 100, '100']], 199, mark=[1], done=[0, 2, 3, 4, 5]), kv=KV([['x-priority', '数大的先拿'], ['低优先级', '高优先级满了才拿'], ['用途', '主备 / 溢出']], ['x-priority'])),
    step("同一个队列里相同的消费者越多越快:prefetch=1、每条 10 ms、800 条。1 个消费者 10.40 s,2 个 5.32 s,4 个 2.74 s,8 个 1.35 s,几乎严格按 1/N 缩短;每个消费者处理的条数几乎相同(8 个时每个 96~103 条)。队列本身不是瓶颈,处理耗时才是——加消费者有效,直到队列或网络成为瓶颈(这里没有测)。", t=tl(S(5)), mark=lidx(S(5), '8    '), done=lidx(S(5), '1    ', '2    ', '4    '), b=bars([['1 个消费者', 10.4, '10.40 s'], ['2 个', 5.32, '5.32 s'], ['4 个', 2.74, '2.74 s'], ['8 个', 1.35, '1.35 s']], 10.4, mark=[3], done=[0, 1, 2]), kv=KV([['N 个消费者', '耗时 ≈ 1/N'], ['每个消费者', '条数几乎相同'], ['瓶颈', '这里是处理耗时']], ['N 个消费者'])),
]
A = mkartq('q9', 9, 'RabbitMQ,公平分发,轮询,prefetch,x-priority,消费者,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上实测消息分发:相同速度的消费者轮流拿;一快一慢时 prefetch=0 要 9.37 s 而 prefetch=1 只要 1.83 s;卡住的消费者扣住的消息数等于 prefetch;x-priority 让高优先级的消费者先拿,满了才溢出;相同消费者 1/2/4/8 个耗时按 1/N 缩短。',
    '“轮询分发”听上去很公平,但一个快一个慢的两个消费者拿到同样多的活时,慢的会拖垮整体。prefetch 怎么把它变成“谁空闲谁拿”?卡住的消费者会扣住多少消息?消费者优先级又是怎么回事?这篇都量一遍。',
    [('9.37 s → 1.83 s', '一快一慢两个消费者处理 600 条:prefetch 不限与 prefetch=1 的总耗时'), ('= prefetch', '卡住的消费者扣住的未确认消息数(1、10、100)'), ('199 / 1', '发布速率 20 条/秒时,优先级 10 与优先级 0 的消费者各拿到的条数')],
    [('轮询', '<p>队列里的消息依次轮流投给订阅它的消费者,但只投给“未确认数 < prefetch”的那些。速度相同时最终各约一半。</p>'),
     ('不公平的来源', '<p>消费者速度不同、prefetch 又很大时,慢的消费者也会持有一大批消息,总耗时被它拖长(prefetch 不限时 9.37 s)。prefetch=1 或很小时,快的消费者空出来就能立刻再拿,接近按速度比例分(1.83 s)。不限 prefetch 时的分法每次运行都不一样,我没有深究原因。</p>'),
     ('卡住的消费者', '<p>消费者收到消息又不处理不确认,它扣住的消息正好是 prefetch 条,别的消费者拿不到。prefetch 越大损失越大。</p>'),
     ('x-priority', '<p>订阅时加参数 <code>x-priority</code>,数大的消费者先拿消息;只有它没空位(prefetch 已满)时才轮到优先级低的。适合做主备或“忙时溢出”。</p>'),
     ('加消费者', '<p>处理耗时固定、prefetch=1 时,N 个相同消费者的总耗时按 1/N 缩短,每个消费者的条数几乎相同。</p>')],
    steps,
    [ENV_Q + '。每个消费者一个线程、一个连接,处理耗时用 time.sleep 模拟;第二节三个设置各跑一次(prefetch=0 的结果每次运行会不同);第四节发布速率用线程按固定间隔发,消费者每条 20 ms',
     '没有验证:prefetch=0 时分配为什么不均衡(可能与 broker 对 channel 的内部流控有关,未查);quorum 队列的分发(delivery-limit 与 consumer 数);消费者数多于队列数据量时的饥饿;单 active consumer(x-single-active-consumer);真实业务中处理耗时不稳定时 prefetch 的取值'],
    '公平分发')
